-- Privileges the policy doesn't give on rowfence's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'fm_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'fm_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'fm_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'fm_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'fm_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowfence''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO fm_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- policy.authz: who can do what in the file manager. Applied by db/migrate.py with authz.apply().
-- Folders nest; what you may do in a folder you may do in everything inside it, unless a folder
-- stops inheritance (inherit = false). People share folders and files with users and groups.

role fm_app

type user = fm.users (id uuid)

type group = fm.groups (id uuid)
  member : user         = fm.group_members(group_id -> user_id)
  member : group#member = fm.groups(parent_id -> id)          -- members of sub-groups count too
  owner  : user         = owner_id
  admin  : user         = fm.group_members(group_id -> user_id) where {is_admin}
  parent : group        = parent_id

  -- who may rename it, add and remove members and sub-groups: its owner, its admins, and those of the groups above
  can manage = owner or admin or parent.manage

type membership = fm.group_members
  group : group = group_id
  person : user = user_id

  can manage = group.manage

type folder = fm.folders
  parent : folder = parent_id
  owner  : user   = owner_id
  viewer : user, group#member, link shared by share
  editor : user, group#member       shared by share

  can share = owner or (parent.share and {inherit})
  can edit  = share or editor or (parent.edit and {inherit})
  can view  = edit or viewer or (parent.view and {inherit})
  -- support staff may give themselves access for a short time: audited, announced (authz.break_glass)
  can break_glass = {exists (select 1 from fm.users u where u.id = authz.uid() and u.is_support)}

type file = fm.files
  folder : folder = folder_id
  owner  : user   = owner_id
  viewer : user, group#member, link shared by share
  editor : user, group#member       shared by share

  can share = owner or folder.share
  can edit  = share or editor or folder.edit
  can view  = edit or viewer or folder.view

-- every stored object is a version of a file, with the file's permissions
type version = fm.file_versions
  file : file = file_id

  can view = file.view
  can edit = file.edit

rules fm.folders
  select                 : view
  insert                 : ({parent_id is null} or parent.edit) and {owner_id = authz.uid()}
  update                 : edit
  update parent_id after : parent.edit or ({parent_id is null} and share)
  update id, owner_id, inherit : share
  delete                 : share

rules fm.files
  select                 : view
  insert                 : folder.edit and {owner_id = authz.uid()} and {fm.key_is_new(object_key)}
  update                 : edit
  update folder_id after : folder.edit
  update id, owner_id    : share
  -- a file shows one of its own versions, never another file's object
  update object_key after : {object_key IN (SELECT v.object_key FROM fm.file_versions v WHERE v.file_id = files.id AND v.ready)}
  delete                 : edit

rules fm.file_versions
  select                 : view
  insert                 : file.edit and {created_by = authz.uid()}
  update                 : edit
  update id, file_id, object_key, created_by : {false}             -- what a version is never changes
  delete                 : edit

-- everyone signed in sees the groups and who is in them (to share with them)
rules fm.groups
  select                 : signed_in
  insert                 : {owner_id = authz.uid()} and ({parent_id is null} or parent.manage)
  update                 : manage
  update parent_id after : {parent_id is null} or parent.manage
  update id, owner_id    : manage
  delete                 : manage

rules fm.group_members
  select                 : signed_in
  insert                 : manage
  update                 : manage
  update group_id after  : manage
  delete                 : manage or person                    -- anyone may leave a group
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+3628ff5402c9', '002aaeafb6dce041');
